/** Q2: เรียกจากจุดที่ผู้เล่นเห็นตัวละครจริง — เปิดการ์ดคู่มือ (ซ้ำได้ ไม่ย้อนกลับ) */
API.markHistory = function (id) {
  if (!id) return false;
  const seen = this.historySeen ||= {};
  if (seen[id]) return false;
  seen[id] = true; return true;
};
